begin;
create extension if not exists pgtap with schema extensions;
select plan(12);
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000001','student@test.invalid'),('00000000-0000-0000-0000-000000000002','nodal@test.invalid'),('00000000-0000-0000-0000-000000000003','other@test.invalid'),('00000000-0000-0000-0000-000000000004','family@test.invalid');
insert into public.pilot_accounts(id,email,name,role,state) values('00000000-0000-0000-0000-000000000001','student@test.invalid','Student','student','Jharkhand'),('00000000-0000-0000-0000-000000000002','nodal@test.invalid','Nodal','nodal','Jharkhand'),('00000000-0000-0000-0000-000000000003','other@test.invalid','Other','student','Odisha'),('00000000-0000-0000-0000-000000000004','family@test.invalid','Family','family',null);
insert into public.pilot_applications(id,data) values('test-app','{"studentId":"00000000-0000-0000-0000-000000000001","schemeId":"pms_st","academicYear":"test","status":"department_stage","profileSnapshot":{"domicileState":"Jharkhand","institutionId":"inst_bitmesra"},"documentIds":[],"ruleSnapshot":{"sanctionAmount":500}}');
select throws_like($$select public.pilot_command('00000000-0000-0000-0000-000000000001','approve_department','{}','{"id":"test-app","version":1}','student-denied')$$,'%forbidden:%','student cannot approve');
select throws_like($$select public.pilot_command('00000000-0000-0000-0000-000000000002','approve_department','{}','{"id":"test-app","version":9}','version-denied')$$,'%conflict:%','stale version rejected');
select throws_like($$select public.pilot_command('00000000-0000-0000-0000-000000000002','approve_department','{}','{"id":"test-app","version":1}','gates-denied')$$,'%human verification required%','missing human reviews prevent approval');
select throws_like($$select public.pilot_command('00000000-0000-0000-0000-000000000002','sanction','{}','{"id":"test-app","version":1}','skip-denied')$$,'%forbidden:%','sanction cannot skip department approval');
select throws_like($$select public.pilot_command('00000000-0000-0000-0000-000000000002','request_payment','{}','{"id":"test-app","version":1}','pay-denied')$$,'%payable sanctioned%','payment requires sanction');
select lives_ok($$select public.pilot_command('00000000-0000-0000-0000-000000000001','create_grievance','{"category":"test","subject":"Help","body":"Test message"}',null,'grievance-op')$$,'grievance command writes');
select lives_ok($$select public.pilot_command('00000000-0000-0000-0000-000000000001','create_grievance','{"category":"test","subject":"Help","body":"Test message"}',null,'grievance-op')$$,'identical retry acknowledged');
select is((select count(*)::int from public.pilot_grievances where data->>'subject'='Help'),1,'retry creates one record');
select throws_like($$select public.pilot_command('00000000-0000-0000-0000-000000000001','create_grievance','{"subject":"different","body":"Test"}',null,'grievance-op')$$,'%operation key reused%','different payload retry rejected');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
set local role authenticated;
select is((select count(*)::int from public.pilot_applications where id='test-app'),0,'another student cannot read application');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
set local role authenticated;
select is((select count(*)::int from public.pilot_applications),0,'family cannot read sensitive base applications');
select is(public.family_summary()->'applications','[]'::jsonb,'family without grant sees no summary');
reset role;
select * from finish();
rollback;
